"""Metric layer: pooled token-level AUROC/AUPRC and mean-aggregated document-level metrics."""
from __future__ import annotations

from typing import Dict, Sequence

import numpy as np
from sklearn.metrics import average_precision_score, roc_auc_score


def token_level_scores(doc_scores: Sequence[Sequence[float]]) -> np.ndarray:
    return np.concatenate([np.asarray(s, dtype=np.float64) for s in doc_scores]) if len(doc_scores) else np.array([])


def document_scores(doc_token_scores: Sequence[Sequence[float]]) -> np.ndarray:
    """Paper Eq. (3) / R5: arithmetic mean of the token scores inside each document."""
    return np.asarray([float(np.mean(s)) for s in doc_token_scores], dtype=np.float64)


def safe_auc(y_true: np.ndarray, scores: np.ndarray) -> float:
    y_true = np.asarray(y_true)
    if y_true.size == 0 or len(np.unique(y_true)) < 2:
        return float("nan")
    return float(roc_auc_score(y_true, scores))


def safe_auprc(y_true: np.ndarray, scores: np.ndarray) -> float:
    y_true = np.asarray(y_true)
    if y_true.size == 0 or len(np.unique(y_true)) < 2:
        return float("nan")
    return float(average_precision_score(y_true, scores))


def evaluate(doc_token_scores: Sequence[Sequence[float]],
             doc_token_labels: Sequence[Sequence[int]],
             doc_labels: Sequence[int]) -> Dict[str, float]:
    """Compute token-level (micro/pooled) and document-level AUROC + AUPRC."""
    tok_scores = token_level_scores(doc_token_scores)
    tok_labels = np.concatenate([np.asarray(l, dtype=np.int64) for l in doc_token_labels]) \
        if len(doc_token_labels) else np.array([], dtype=np.int64)
    if tok_scores.shape[0] != tok_labels.shape[0]:
        raise RuntimeError("token score/label length mismatch")

    doc_sc = document_scores(doc_token_scores)
    doc_lab = np.asarray(doc_labels, dtype=np.int64)

    return {
        "token_auroc": safe_auc(tok_labels, tok_scores),
        "token_auprc": safe_auprc(tok_labels, tok_scores),
        "doc_auroc": safe_auc(doc_lab, doc_sc),
        "doc_auprc": safe_auprc(doc_lab, doc_sc),
        "n_test_tokens": int(tok_scores.shape[0]),
        "n_positive_tokens": int(tok_labels.sum()),
        "n_test_docs": int(doc_lab.shape[0]),
        "n_positive_docs": int(doc_lab.sum()),
        "token_positive_rate": float(tok_labels.mean()) if tok_labels.size else float("nan"),
    }


def random_control(doc_token_labels: Sequence[Sequence[int]], seed: int = 12345) -> Dict[str, float]:
    """Random-score control: AUROC should sit near 0.5 and AUPRC near the positive rate."""
    rng = np.random.RandomState(seed)
    labels = np.concatenate([np.asarray(l, dtype=np.int64) for l in doc_token_labels])
    scores = rng.rand(labels.shape[0])
    return {
        "random_token_auroc": safe_auc(labels, scores),
        "random_token_auprc": safe_auprc(labels, scores),
    }


def metric_parity_check() -> Dict[str, float]:
    """Verify our AUROC/AUPRC plumbing against sklearn on synthetic labels."""
    rng = np.random.RandomState(0)
    y = rng.randint(0, 2, 500)
    s = rng.rand(500)
    return {
        "sklearn_token_auroc": float(roc_auc_score(y, s)),
        "sklearn_token_auprc": float(average_precision_score(y, s)),
        "ours_token_auroc": safe_auc(y, s),
        "ours_token_auprc": safe_auprc(y, s),
    }
